"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface ListTodoIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface ListTodoIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const ListTodoIcon = forwardRef<ListTodoIconHandle, ListTodoIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const rowVariants: Variants = {
   normal: { scaleX: 1 },
   animate: (i: number) => ({
    scaleX: [1, 0.55, 1],
    transition: {
     duration: 0.5 * duration,
     ease: "easeInOut",
     delay: (0.05 + i * 0.12) * duration,
    },
   }),
  };

  const boxVariants: Variants = {
   normal: { rotate: 0 },
   animate: {
    rotate: [0, -10, 6, -2, 0],
    transition: { duration: 0.6 * duration, ease: "easeInOut" },
   },
  };

  const tickVariants: Variants = {
   normal: { strokeDashoffset: 0, opacity: 1, scale: 1 },
   animate: {
    strokeDashoffset: [9, 0],
    opacity: [0, 1],
    scale: [0.8, 1.12, 1],
    transition: {
     strokeDashoffset: {
      duration: 0.45 * duration,
      ease: "easeOut",
      delay: 0.15 * duration,
     },
     opacity: { duration: 0.25 * duration, delay: 0.15 * duration },
     scale: {
      duration: 0.45 * duration,
      delay: 0.19 * duration,
      times: [0, 0.6, 1],
      ease: "easeInOut",
     },
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M13 5h8"
       variants={rowVariants}
       custom={0}
       style={{ transformBox: "view-box", originX: "13px", originY: "5px" }}
      />
      <m.path
       d="M13 12h8"
       variants={rowVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "13px", originY: "12px" }}
      />
      <m.path
       d="M13 19h8"
       variants={rowVariants}
       custom={2}
       style={{ transformBox: "view-box", originX: "13px", originY: "19px" }}
      />
      <m.path
       d="m3 17 2 2 4-4"
       strokeDasharray="9"
       strokeDashoffset="0"
       variants={tickVariants}
       style={{ transformBox: "view-box", originX: "6px", originY: "17px" }}
      />
      <m.rect
       x="3"
       y="4"
       width="6"
       height="6"
       rx="1"
       variants={boxVariants}
       style={{ transformBox: "view-box", originX: "6px", originY: "7px" }}
      />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

ListTodoIcon.displayName = "ListTodoIcon";
export { ListTodoIcon };
